/// <summary>
/// Extension class for METFTIWorkflowExclusionParameters to add custom methods.
/// </summary>
/// Added for CFR41 Bulk AR Invoice approval.
public class METFTIWorkflowExclusionParameters extends common
{
}

Method.Source:
/// <summary>
/// Retrieves the user name.
/// </summary>
/// <returns>
/// A string that contains the user name.
/// </returns>
[SysClientCacheDataMethod(true)]
public display UserIdStr getUserName()
{
    UserInfo userInfo;

    if (this.UserId)
    {
        select firstonly name from userInfo
            where userInfo.Id == this.UserId;
    }

    return (userInfo.name) ? userInfo.name : '';
}

/// <summary>
///  Finds a record in the <c>METFTIWorkflowExclusionParameters</c> table.
/// </summary>
/// <param name="_forUpdate">
/// A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>METFTIWorkflowExclusionParameters buffer</returns>
public static METFTIWorkflowExclusionParameters find(boolean _forUpdate = false)
{
    METFTIWorkflowExclusionParameters parameters;

    parameters.selectForUpdate(_forUpdate);

    select firstonly parameters
        where parameters.RecId == 0;

    if (!parameters && !parameters.isTmp())
    {
        Company::createParameter(parameters);
    }

    return parameters;
}

/// <summary>
/// Indicates whether the workflow exclusion parameters is exists or not.
/// </summary>
/// <returns>true if the workflow exclusion parameters exists; else false.</returns>
public static boolean exist()
{
    METFTIWorkflowExclusionParameters parameters;

    select firstonly RecId from parameters;

    return (parameters.RecId != 0);
}

/// <summary>
/// Validate the records before deleting.
/// </summary>
/// <returns>true if it's succeeded; else false.</returns>
public boolean validateDelete()
{
    boolean ret;

    ret = super();

    //Show this custom message
    if (ret && FormDataUtil::isFormDataSource(this))
    {
        CustInvoiceTable custInvoiceTable;

        select firstonly RecId from custInvoiceTable
            where custInvoiceTable.CreatedBy == this.UserId &&
                custInvoiceTable.Posted == NoYes::No;

        if (custInvoiceTable.RecId != 0)
        {
            ret = Box::yesNo("@MET:METFTIWFExclusionDeleteWarning",DialogButton::No) == DialogButton::Yes;
        }
    }

    return ret;
}
